diff --git a/src/value.rs b/src/value.rs
index d61a059..39f0eb7 100644
--- a/src/value.rs
+++ b/src/value.rs
@@ -53,13 +53,19 @@ pub fn parse_value(raw: &str) -> Value {
     if let Ok(n) = s.parse::<i64>() {
         return Value::Int(n);
     }
-    match s {
+    match s.to_ascii_lowercase().as_str() {
         "true" => return Value::Bool(true),
         "false" => return Value::Bool(false),
         _ => {}
     }
     if s.contains(',') {
-        return Value::List(s.split(',').map(str::trim).map(String::from).collect());
+        return Value::List(
+            s.split(',')
+                .map(str::trim)
+                .filter(|item| !item.is_empty())
+                .map(String::from)
+                .collect(),
+        );
     }
     Value::Str(s.trim_matches('"').to_string())
 }

